Yes, here's a JavaScript function that takes a sentence as input and returns a new sentence with the order of adjectives reversed:

```javascript
function reverseAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find all the words that are adjectives (have more than one consonant at the beginning)
  const adjectives = [];
  for (let I = 0; I < words.length; i++) {
    const word = words[i];
    let hasConsonants = false;
    for (let j = 1; j < word.length; j++) {
      if (word[j - 1] !== 'e' && word[j] !== 'a') {
        hasConsonants = true;
        break;
      }
    }
    if (hasConsonants) {
      adjectives.push(word);
    }
  }

  // Reverse the order of the adjectives and concatenate them back into a string
  const reversedAdjectives = adjectives.reverse().join(" ");

  // Combine the reversed adjectives with the non-adjective words in their original order
  const result = reversedAdjectives + " " + words.filter(word => !adjectives.includes(word)).join(" ");

  return result;
}
```

Here's how you could use it:

```javascript
const originalSentence = "Beautiful green trees are in the park";
const reversedSentence = reverseAdjectives(originalSentence);
console.log(reversedSentence); // Output: "Green beautiful trees are in the park"
```

