```javascript
function sortJsonByKeys(jsonStr) {
  const obj = JSON.parse(jsonStr); // converting JSON to JS object
  const keys = Object.keys(obj).sort(); // getting all the keys and sorting them
  const sortedObj = {}; // creating an empty object to store the sorted result

  for (let I = 0; I < keys.length; i++) { // iterating through sorted keys
    sortedObj[keys[i]] = obj[keys[i]]; // adding each key-value pair to the sorted object
  }

  return JSON.stringify(sortedObj); // converting sorted object to JSON string
}
```

